{"packet_id":"D029-01","doc_id":"D029","jurisdiction":"Cambridge, MA","category":"screening_restrictions","lifecycle":"enacted","title":"Cambridge Fair Housing Ordinance source-of-income protection","requirement":"Landlords, sellers and rental agents may not discriminate in housing because of a person's source of income, which includes Section 8 and public benefits, in renting or in the terms and conditions of tenancy.","key_value":null,"coverage_conditions":"Real estate transactions in Cambridge, including viewing or renting an apartment and the terms and conditions of tenancy.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Two-family dwellings where the owner lives there are exempt"},"exemptions":"There is an exemption for 2-family dwellings, when the owner lives there.","penalty":"Civil fines of up to $300 for each violation; injunction, damages and expenses may be sought in Superior Court.","effective_date":null,"citation":"Cambridge Fair Housing Ordinance ch. 14.04","quoted_span":"Source of Income, includes Section 8 and public benefits","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D029-01","doc_id":"D029","jurisdiction":"Cambridge, MA","category":"screening_restrictions","lifecycle":"enacted","title":"Cambridge Fair Housing Ordinance tenant selection standards","requirement":"Landlords, sellers and rental agents may use any reasonable standard to select tenants only if it is applied equally and uniformly to all applicants; selection may rest on ability to pay rent and to care for the apartment and respect others' rights.","key_value":null,"coverage_conditions":"Housing rentals in Cambridge; the page states landlords, sellers and rental agents may apply reasonable, equally applied standards when selecting tenants.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Two-family dwellings where the owner lives there are exempt"},"exemptions":"There is an exemption for 2-family dwellings, when the owner lives there.","penalty":null,"effective_date":null,"citation":"Cambridge Fair Housing Ordinance ch. 14.04","quoted_span":"Under the law, landlords, sellers and rental agents may use any reasonable standard to determine which applicants are selected, as long as that standard is applied equally and uniformly to all applicants.","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
